10	var (
11		ErrDeviceNotFound = errors.New("device not found")
12		ErrBatchConflict  = errors.New("batch conflicts with stored events")
13	)
14	
15	type Device struct {
16		ID            string             `json:"id"`
17		Site          string             `json:"site"`
18		RegisteredAt  time.Time          `json:"registeredAt"`
19		LastSeenAt    time.Time          `json:"lastSeenAt"`
20		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
21	}
22	
23	// Event is a single telemetry sample retained in a device's history.
24	type Event struct {
25		Sequence   int64              `json:"sequence"`
26		ObservedAt time.Time          `json:"observedAt"`
27		Values     map[string]float64 `json:"values"`
28	}
