37	// ReplayReceipt summarises the outcome of a replay batch.
38	type ReplayReceipt struct {
39		BatchID      string         `json:"batchId"`
40		NewCount     int            `json:"newCount"`
41		Duplicate    int            `json:"duplicateCount"`
42		SampleStatus []SampleStatus `json:"samples"`
43	}
