53	// the bound is open.
54	type HistoryFilter struct {
55		From time.Time
56		To   time.Time
57	}
58	
59	// StoredBatch records the ordered samples an accepted batchId committed along
60	// with the receipt returned on first acceptance, so a repeated batchId can be
61	// checked for identical content and replayed with the original receipt.
62	type storedBatch struct {
63		samples []Sample
64		receipt ReplayReceipt
65	}
66	
67	type deviceState struct {
68		device  Device
69		events  []Event          // history ordered by sequence (sequence = index + 1)
70		byEvent map[string]int64 // eventId -> sequence
71		batches map[string]storedBatch
72	}
73	
74	type Store struct {
75		mu      sync.RWMutex
76		devices map[string]*deviceState
77		now     func() time.Time
78	}
79	
80	func NewStore() *Store {
81		return &Store{devices: make(map[string]*deviceState), now: time.Now}
82	}
83	
84	// Exists reports whether a device is registered.
85	func (s *Store) Exists(id string) bool {
86		s.mu.RLock()
87		defer s.mu.RUnlock()
88		_, ok := s.devices[id]
89		return ok
90	}
