92	func (s *Store) Register(id, site string) (Device, bool) {
93		s.mu.Lock()
94		defer s.mu.Unlock()
95		if state, ok := s.devices[id]; ok {
96			return cloneDevice(state.device), false
97		}
98		now := s.now().UTC()
99		device := Device{ID: id, Site: site, RegisteredAt: now, LastSeenAt: now}
100		s.devices[id] = &deviceState{
101			device:  device,
102			byEvent: make(map[string]int64),
103			batches: make(map[string]storedBatch),
104		}
105		return cloneDevice(device), true
106	}
107	
108	// RecordTelemetry stores a live telemetry sample in the device history. The
109	// sample has no caller-supplied eventId, so it is never a replay duplicate; its
110	// observed time is the server receive time.
111	func (s *Store) RecordTelemetry(id string, values map[string]float64) (Device, error) {
112		s.mu.Lock()
113		defer s.mu.Unlock()
114		state, ok := s.devices[id]
115		if !ok {
116			return Device{}, ErrDeviceNotFound
117		}
118		now := s.now().UTC()
119		state.events = append(state.events, Event{
120			Sequence:   int64(len(state.events)) + 1,
121			ObservedAt: now,
122			Values:     cloneTelemetry(values),
123		})
124		state.device.LastSeenAt = now
125		state.device.LastTelemetry = cloneTelemetry(values)
126		return cloneDevice(state.device), nil
127	}
128	
129	// Replay validates and commits a batch atomically. repeat is true when the
130	// batchId was already committed with identical content and the first receipt
131	// is returned unchanged. It returns ErrDeviceNotFound for an unknown device and
132	// ErrBatchConflict when any sample clashes with an existing eventId or the
133	// batchId was previously committed with different ordered content; in either
134	// conflict case no state changes.
135	func (s *Store) Replay(id, batchID string, samples []Sample) (receipt ReplayReceipt, repeat bool, err error) {
136		s.mu.Lock()
137		defer s.mu.Unlock()
138		state, ok := s.devices[id]
139		if !ok {
140			return ReplayReceipt{}, false, ErrDeviceNotFound
141		}
142	
143		if previous, exists := state.batches[batchID]; exists {
144			if !sameOrderedSamples(previous.samples, samples) {
145				return ReplayReceipt{}, false, ErrBatchConflict
146			}
147			return cloneReceipt(previous.receipt), true, nil
148		}
149	
150		// Validate every sample against committed history before appending so a
151		// conflict rolls back without leaving sequences, events or receipts.
152		type plan struct {
153			sample   Sample
154			sequence int64
155			dup      bool
156		}
157		planned := make([]plan, len(samples))
158		nextSequence := int64(len(state.events)) + 1
159		for i, sample := range samples {
160			if sequence, seen := state.byEvent[sample.EventID]; seen {
161				existing := state.events[sequence-1]
162				if !sameInstant(existing.ObservedAt, sample.ObservedAt) ||
163					!sameValues(existing.Values, sample.Values) {
164					return ReplayReceipt{}, false, ErrBatchConflict
165				}
166				planned[i] = plan{sample, sequence, true}
167				continue
168			}
169			planned[i] = plan{sample, nextSequence, false}
170			nextSequence++
171		}
172	
173		// Build the receipt from the plan: only samples that matched a committed
174		// event before this batch are duplicates.
175		receipt = ReplayReceipt{BatchID: batchID, SampleStatus: make([]SampleStatus, 0, len(samples))}
176		for _, entry := range planned {
177			receipt.SampleStatus = append(receipt.SampleStatus, SampleStatus{
178				EventID:   entry.sample.EventID,
179				Sequence:  entry.sequence,
180				Duplicate: entry.dup,
181			})
182			if entry.dup {
183				receipt.Duplicate++
184			} else {
185				receipt.NewCount++
186			}
187		}
188	
189		// Commit: append new samples in array order.
190		lastNew := -1
191		for i, entry := range planned {
192			if entry.dup {
193				continue
194			}
195			state.events = append(state.events, Event{
196				Sequence:   entry.sequence,
197				ObservedAt: entry.sample.ObservedAt,
198				Values:     cloneTelemetry(entry.sample.Values),
199			})
200			state.byEvent[entry.sample.EventID] = entry.sequence
201			lastNew = i
202		}
203	
204		committed := make([]Sample, len(samples))
205		copy(committed, samples)
206		for i := range committed {
207			committed[i].Values = cloneTelemetry(samples[i].Values)
208		}
209		state.batches[batchID] = storedBatch{samples: committed, receipt: cloneReceipt(receipt)}
210	
211		if lastNew >= 0 {
212			now := s.now().UTC()
213			state.device.LastSeenAt = now
214			state.device.LastTelemetry = cloneTelemetry(samples[lastNew].Values)
215		}
216		return receipt, false, nil
217	}
218	
219	func cloneReceipt(receipt ReplayReceipt) ReplayReceipt {
220		receipt.SampleStatus = append([]SampleStatus(nil), receipt.SampleStatus...)
221		return receipt
222	}
223	
224	// History returns one page of a device's event history. afterIndex is the first
225	// 0-based event slot to scan (0 for the first page); limit caps the number of
226	// matching events returned. bound pins the scan to sequences no larger than
227	// bound; a zero bound means "current maximum", which is then returned so
228	// callers can pin subsequent pages. nextIndex is the slot a following page
229	// should start at when hasMore is true. Concurrent writes therefore cannot
230	// skip or duplicate rows within a paged walk.
231	func (s *Store) History(id string, filter HistoryFilter, afterIndex, bound int64, limit int) (events []Event, appliedBound, nextIndex int64, hasMore bool, err error) {
232		s.mu.RLock()
233		defer s.mu.RUnlock()
234		state, ok := s.devices[id]
235		if !ok {
236			return nil, 0, 0, false, ErrDeviceNotFound
237		}
238		highWater := int64(len(state.events))
239		if bound == 0 {
240			bound = highWater
241		}
242		events = make([]Event, 0, limit)
243		for index := afterIndex; index < bound; index++ {
244			event := state.events[index]
245			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
246				continue
247			}
248			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
249				continue
250			}
251			if len(events) < limit {
252				events = append(events, cloneEvent(event))
253				continue
254			}
255			// This match belongs to the next page; resume scanning here so rows in
256			// the gap are never examined twice.
257			return events, bound, index, true, nil
258		}
259		return events, bound, bound, false, nil
260	}
261	
262	func (s *Store) Snapshot() []Device {
263		s.mu.RLock()
264		defer s.mu.RUnlock()
265		result := make([]Device, 0, len(s.devices))
266		for _, state := range s.devices {
267			result = append(result, cloneDevice(state.device))
268		}
269		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
270		return result
271	}
272	
273	func cloneDevice(device Device) Device {
274		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
275		return device
276	}
277	
278	func cloneEvent(event Event) Event {
279		event.Values = cloneTelemetry(event.Values)
280		return event
281	}
282	
283	func cloneTelemetry(values map[string]float64) map[string]float64 {
284		if values == nil {
285			return nil
286		}
287		cloned := make(map[string]float64, len(values))
288		for key, value := range values {
289			cloned[key] = value
290		}
291		return cloned
292	}
293	
294	// sameInstant compares times as UTC instants.
295	func sameInstant(a, b time.Time) bool {
296		return a.UTC().Equal(b.UTC())
297	}
298	
299	// sameValues compares metric maps by key and value.
300	func sameValues(a, b map[string]float64) bool {
301		if len(a) != len(b) {
302			return false
303		}
304		for key, value := range a {
305			other, ok := b[key]
306			if !ok || value != other {
307				return false
308			}
309		}
310		return true
311	}
312	
313	// sameOrderedSamples reports whether two batches carry the same samples in the
314	// same order, compared as UTC instants and key/value maps.
315	func sameOrderedSamples(a, b []Sample) bool {
316		if len(a) != len(b) {
317			return false
318		}
319		for i := range a {
320			if a[i].EventID != b[i].EventID ||
321				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
322				!sameValues(a[i].Values, b[i].Values) {
323				return false
324			}
325		}
326		return true
327	}
