70	func newClockStore() (*Store, *time.Time) {
71		store := NewStore()
72		clock := time.Date(2024, time.January, 1, 0, 0, 0, 0, time.UTC)
73		store.now = func() time.Time { return clock }
74		return store, &clock
75	}
