77	func doRequest(t *testing.T, h http.Handler, method, target, body string) *httptest.ResponseRecorder {
78		t.Helper()
79		var reader *strings.Reader
80		if body != "" {
81			reader = strings.NewReader(body)
82		} else {
83			reader = strings.NewReader("")
84		}
85		request := httptest.NewRequest(method, target, reader)
86		request.Header.Set("Content-Type", "application/json")
87		result := httptest.NewRecorder()
88		h.ServeHTTP(result, request)
89		return result
90	}
