195	func TestReplayNewBatchReturns202AndReceipt(t *testing.T) {
196		store, clock := newClockStore()
197		h := NewHandler(store)
198		mustRegister(t, h, "gw")
199	
200		body := replayBody("batch-1",
201			sample("e1", "2024-01-02T10:00:00Z", `{"a":1}`),
202			sample("e2", "2024-01-02T11:00:00Z", `{"b":2}`),
203		)
204		result := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", body)
205		if result.Code != http.StatusAccepted {
206			t.Fatalf("status = %d, want 202: %s", result.Code, result.Body.String())
207		}
208		receipt := decodeBody[receiptResponse](t, result)
209		if receipt.NewCount != 2 || receipt.DuplicateCount != 0 {
210			t.Fatalf("counts = %+d/%d, want 2/0", receipt.NewCount, receipt.DuplicateCount)
211		}
212		if len(receipt.Samples) != 2 || receipt.Samples[0].Sequence != 1 || receipt.Samples[1].Sequence != 2 {
213			t.Fatalf("receipt samples = %+v", receipt.Samples)
214		}
215		if receipt.Samples[0].Duplicate || receipt.Samples[1].Duplicate {
216			t.Fatalf("new batch must not mark duplicates: %+v", receipt.Samples)
217		}
218	
219		// Events land in array order; the last new sample drives the snapshot.
220		events := allEvents(t, h, "gw")
221		if len(events) != 2 || events[0].Sequence != 1 || events[1].Sequence != 1+1 {
222			t.Fatalf("history = %+v", events)
223		}
224		snapshot := decodeBody[struct {
225			Devices []Device `json:"devices"`
226		}](t, doRequest(t, h, http.MethodGet, "/v1/fleet", ""))
227		if len(snapshot.Devices) != 1 || snapshot.Devices[0].LastTelemetry["b"] != 2 {
228			t.Fatalf("snapshot lastTelemetry = %+v, want b:2 from last new sample", snapshot.Devices)
229		}
230		if !snapshot.Devices[0].LastSeenAt.Equal(*clock) {
231			t.Fatalf("lastSeenAt = %s, want receive time %s", snapshot.Devices[0].LastSeenAt, *clock)
232		}
233	}
