	for i, page := range pages {
		if len(page.Events) != wantSizes[i] {
			t.Fatalf("page %d size = %d, want %d", i, len(page.Events), wantSizes[i])
		}
		for _, event := range page.Events {
			seen++
			if event.Sequence != seen {
