// walFile is the on-disk WAL. durable is the length of records known to be
// intact; writes always land at durable via pwrite, so a torn record from a
// failed write is overwritten by the next attempt instead of trapping later
// committed records behind it.
type walFile struct {
	f       *os.File
	lock    *os.File
	mu      sync.Mutex
	durable int64
}

func (w *walFile) appendRecord(recType byte, value any) error {
	buf, err := marshalFrame(recType, value)
	if err != nil {
		return err
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	n, err := w.f.WriteAt(buf, w.durable)
	if err != nil {
		return err
	}
	if n != len(buf) {
		return fmt.Errorf("short wal write: %d of %d bytes", n, len(buf))
	}
	if err := w.f.Sync(); err != nil {
		return err
	}
	w.durable += int64(len(buf))
	return nil
}

