// walFile is the on-disk WAL. durable is the length of committed frames. A
// frame is published in two synced phases — body then commit marker — so a
// write that is interrupted before success leaves no marker behind. Every
// write lands at durable via pwrite, so residue from a failed write is
// overwritten by the next attempt instead of trapping later committed records.
type walFile struct {
	f       *os.File
	lock    *os.File
	mu      sync.Mutex
	durable int64
}

func (w *walFile) appendRecord(recType byte, value any) error {
	body, total, err := marshalFrame(recType, value)
	if err != nil {
		return err
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	// Phase 1: persist body ([length][type][payload][checksum]).
	if err := pwriteAll(w.f, body, w.durable); err != nil {
		return err
	}
	if err := w.f.Sync(); err != nil {
		return err
	}
	// Phase 2: publish the commit marker. durable only advances afterwards,
	// so an interruption in phase 1 or before this fsync leaves an
	// unacknowledged, unmarked tail that recovery discards.
	if err := pwriteAll(w.f, []byte(commitMagic), w.durable+int64(len(body))); err != nil {
		return err
	}
	if err := w.f.Sync(); err != nil {
		return err
	}
	w.durable += int64(total)
	return nil
}

func pwriteAll(f *os.File, buf []byte, offset int64) error {
	for len(buf) > 0 {
		n, err := f.WriteAt(buf, offset)
		if err != nil {
			return err
		}
		buf = buf[n:]
		offset += int64(n)
	}
	return nil
}

