// marshalFrame frames one record as [length uint32 LE][type byte][payload][checksum8].
// The checksum covers type and payload and is the first 8 bytes of SHA-256.
func marshalFrame(recType byte, value any) ([]byte, error) {
	payload, err := json.Marshal(value)
	if err != nil {
		return nil, err
	}
	if len(payload) > maxRecordPayload {
		return nil, fmt.Errorf("wal record too large: %d bytes", len(payload))
	}
	buf := make([]byte, 5+len(payload)+8)
	binary.LittleEndian.PutUint32(buf[0:4], uint32(len(payload)))
	buf[4] = recType
	copy(buf[5:], payload)
