	if r.Code != http.StatusAccepted {
		t.Fatalf("retried write = %d: %s", r.Code, r.Body.String())
	}
	events = allEvents(t, h, "gw")
	if len(events) != 1 || events[0].Sequence != 1 {
		t.Fatalf("retry did not commit at sequence 1: %+v", events)
