// --- replay batch atomicity across a crash ----------------------------------

func TestPersistentReplayIsOneCommitUnit(t *testing.T) {
	dir := t.TempDir()
	store := openPersistent(t, dir)
	h := NewHandler(store)
	mustRegister(t, h, "gw")

	// Commit a three-sample batch, then append a *complete but unmarked* frame
	// (phase 1 survived, phase 2 did not): recovery must expose none of it.
