// marshalFrame frames one record as
// [length uint32 LE][type byte][payload][checksum8][commit marker 4].
// The checksum covers the whole phase-1 body (length, type and payload) and is
// the first 8 bytes of SHA-256. It returns the phase-1 body and the total
// committed frame length.
func marshalFrame(recType byte, value any) (body []byte, total int, err error) {
	payload, err := json.Marshal(value)
	if err != nil {
		return nil, 0, err
	}
	if len(payload) > maxRecordPayload {
		return nil, 0, fmt.Errorf("wal record too large: %d bytes", len(payload))
	}
	body = make([]byte, 5+len(payload)+8)
	binary.LittleEndian.PutUint32(body[0:4], uint32(len(payload)))
	body[4] = recType
	copy(body[5:], payload)
	sum := sha256.Sum256(body[:5+len(payload)])
	copy(body[5+len(payload):], sum[:8])
	return body, len(body) + len(commitMagic), nil
}

const (
	frameOK           = iota // fully committed: checksum valid, marker present
	frameUncommitted         // whole frame present but not committed (marker absent/invalid)
	frameTruncated           // declared frame runs past the end of the file
	frameCorrupt             // committed frame present but its checksum is bad
)

// classifyFrame inspects the frame beginning at pos using the two-phase commit
// layout. The commit marker is only written after a complete, synced body, so:
// a bad checksum together with the marker proves bit-rot of committed data; a
// fully present frame without a marker is an unacknowledged phase-1/phase-2
// write; and a declared frame reaching past end-of-file is a torn phase-1
// tail. The last two are ambiguous only when further committed frames
// somehow follow them, which the caller checks with hasCommittedChain.
func classifyFrame(data []byte, pos int) (status int, end int, recType byte, payload []byte) {
	if pos+5 > len(data) {
		return frameTruncated, len(data), 0, nil
	}
	length := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
	frameLen := 5 + length + 8 + len(commitMagic)
	if length < 0 || length > maxRecordPayload || pos+frameLen > len(data) {
		return frameTruncated, len(data), 0, nil
	}
	recType = data[pos+4]
	payload = data[pos+5 : pos+5+length]
	sum := sha256.Sum256(data[pos : pos+5+length])
	checksumOK := bytes.Equal(sum[:8], data[pos+5+length:pos+5+length+8])
	markerOK := string(data[pos+5+length+8:pos+frameLen]) == commitMagic
	end = pos + frameLen
	switch {
	case checksumOK && markerOK:
		return frameOK, end, recType, payload
	case checksumOK:
		return frameUncommitted, end, 0, nil
	case markerOK:
		return frameCorrupt, end, 0, nil
	default:
		return frameUncommitted, end, 0, nil
	}
}

// hasCommittedChain reports whether valid committed frames chain contiguously
// from some offset at or after start to the exact end of data. Such a chain
// means the unusable bytes at start were followed by acknowledged writes and
// therefore belong to committed history rather than an unacknowledged tail.
// Valid logs written by this server are frame-contiguous, so outside of
// on-disk damage the scan finds nothing.
func hasCommittedChain(data []byte, start int) bool {
	for q := start + 1; q < len(data); q++ {
		status, cur, recType, _ := classifyFrame(data, q)
		if status != frameOK || recType < recInstance || recType > recReplay {
			continue
		}
		for cur < len(data) {
			next, t, _, good := classifyFrame(data, cur)
			if !good || next != frameOK || t < recInstance || t > recReplay {
				break
			}
			cur = cur // no-op to keep linter calm
			_ = t
			break
		}
		// Walk the chain explicitly.
		at := cur
		for at < len(data) {
			next, t, _, good := classifyFrame(data, at)
			if good != frameOK || t < recInstance || t > recReplay {
				break
			}
			at = next
		}
		if at == len(data) {
			return true
		}
	}
	return false
}

