// parseFrame verifies one fully committed frame at pos. ok is false when the
// frame is truncated, checksum-damaged, or carries anything other than the
// commit marker — those cases are indistinguishable corruption on disk and are
// resolved by the caller according to whether further committed frames exist.
func parseFrame(data []byte, pos int) (end int, recType byte, payload []byte, ok bool) {
	if pos+5 > len(data) {
		return 0, 0, nil, false
	}
	length := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
	frameLen := 5 + length + 8 + len(commitMagic)
	if length < 0 || length > maxRecordPayload || pos+frameLen > len(data) {
		return 0, 0, nil, false
	}
	recType = data[pos+4]
	payload = data[pos+5 : pos+5+length]
	sum := sha256.Sum256(data[pos+4 : pos+5+length])
	if !bytes.Equal(sum[:8], data[pos+5+length:pos+5+length+8]) {
		return 0, 0, nil, false
	}
	if string(data[pos+5+length+8:pos+frameLen]) != commitMagic {
		return 0, 0, nil, false
	}
	return pos + frameLen, recType, payload, true
}

// scanCommitted verifies the committed frame at pos. It reports the frame end
// and contents on success. A bad frame is "unacknowledged tail" when no valid
// committed frame chain resumes behind it and reaches the exact end of data; if
// such a chain exists, the bad frame was committed data and the log is corrupt.
func scanCommitted(data []byte, pos int) (end int, recType byte, payload []byte, corrupt bool) {
	if e, t, p, ok := parseFrame(data, pos); ok {
		return e, t, p, false
	}
	for q := pos + 1; q < len(data); q++ {
		cur, t, _, good := parseFrame(data, q)
		if !good || t < recInstance || t > recReplay {
			continue
		}
		for cur < len(data) {
			e, nextType, _, chainOK := parseFrame(data, cur)
			if !chainOK || nextType < recInstance || nextType > recReplay {
				break
			}
			cur = e
		}
		if cur == len(data) {
			return 0, 0, nil, true
		}
	}
	return pos, 0, nil, false
}

