125			return err
126		}
127		if err := w.f.Sync(); err != nil {
128			return err
129		}
130		w.durable += int64(total)
131		return nil
132	}
133	
134	func pwriteAll(f *os.File, buf []byte, offset int64) error {
135		for len(buf) > 0 {
136			n, err := f.WriteAt(buf, offset)
137			if err != nil {
138				return err
139			}
140			buf = buf[n:]
141			offset += int64(n)
142		}
143		return nil
144	}
145	
146	func (w *walFile) Close() error {
147		writeErr := w.f.Close()
148		// Closing the lock fd releases the flock; a killed process releases it via
149		// the kernel, so no manual lock cleanup is ever required.
150		lockErr := w.lock.Close()
151		if writeErr != nil {
152			return writeErr
153		}
154		return lockErr
155	}
156	
157	// NewPersistentStore opens (or creates) a data directory and finishes full
158	// recovery before returning. It fails rather than falling back to memory when
159	// the directory cannot be created, locked, read or written, when another
160	// process already holds the directory, or when committed data is corrupt or
161	// in an unsupported format.
162	func NewPersistentStore(dir string) (_ *Store, err error) {
163		if fi, statErr := os.Stat(dir); statErr == nil {
164			if !fi.IsDir() {
165				return nil, fmt.Errorf("data path %s is not a directory", dir)
166			}
167		} else if !errors.Is(statErr, fs.ErrNotExist) {
168			return nil, fmt.Errorf("cannot access data directory %s: %w", dir, statErr)
169		}
170		if err := os.MkdirAll(dir, 0o755); err != nil {
171			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
172		}
173	
174		// Take the inter-process lock before reading or writing any business data.
175		lockPath := filepath.Join(dir, lockName)
176		lockFile, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
177		if err != nil {
178			return nil, fmt.Errorf("cannot open lock file %s: %w", lockPath, err)
179		}
180		if lockErr := syscall.Flock(int(lockFile.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); lockErr != nil {
181			_ = lockFile.Close()
182			return nil, fmt.Errorf("data directory %s is already in use by another edge-fleet process: %w", dir, lockErr)
183		}
184	
185		walPath := filepath.Join(dir, walName)
186		f, err := os.OpenFile(walPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
187		if err != nil {
188			_ = lockFile.Close()
189			return nil, fmt.Errorf("cannot open write-ahead log %s: %w", walPath, err)
190		}
191		committed := false
192		defer func() {
193			if !committed {
194				_ = f.Close()
195				_ = lockFile.Close()
196			}
197		}()
198	
199		fi, err := f.Stat()
200		if err != nil {
201			return nil, fmt.Errorf("cannot stat write-ahead log %s: %w", walPath, err)
202		}
203		if fi.Size() == 0 {
204			if _, err := f.WriteAt(walHeader(), 0); err != nil {
205				return nil, fmt.Errorf("cannot initialise write-ahead log %s: %w", walPath, err)
206			}
207			if err := f.Sync(); err != nil {
208				return nil, fmt.Errorf("cannot flush write-ahead log %s: %w", walPath, err)
209			}
210		}
211	
212		if _, err := f.Seek(0, io.SeekStart); err != nil {
213			return nil, err
214		}
215		data, err := io.ReadAll(f)
216		if err != nil {
217			return nil, fmt.Errorf("cannot read write-ahead log %s: %w", walPath, err)
218		}
219		if len(data) < headerLen || string(data[0:8]) != walMagic {
220			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad magic header", walPath)
221		}
222		version := binary.LittleEndian.Uint32(data[8:12])
223		if version != walVersion {
224			return nil, fmt.Errorf("write-ahead log %s uses unsupported format version %d (this server supports %d)", walPath, version, walVersion)
225		}
226		if binary.LittleEndian.Uint32(data[12:16]) != 0 {
227			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad header flags", walPath)
228		}
229	
230		store := NewStore()
231		var instanceID []byte
232		sawInstance := false
233		pos := headerLen
234		for pos < len(data) {
235			status, end, recType, payload := classifyFrame(data, pos)
236			switch status {
237			case frameOK:
238				// continue below to apply the record
239			case frameCorrupt:
240				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: committed record failed its integrity check (file left untouched)", walPath, pos)
241			case frameUncommitted, frameTruncated:
242				// Residue of a write that never reached its commit marker: only
243				// legal as the unacknowledged tail of the log.
244				if hasCommittedChain(data, pos) {
245					return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: uncommitted frame with committed records following it (file left untouched)", walPath, pos)
246				}
247				end = -1
248			}
249			if end == -1 {
250				break
251			}
252			switch recType {
253			case recInstance:
254				if sawInstance || pos != headerLen {
255					return nil, fmt.Errorf("write-ahead log %s is corrupt: instance marker out of place", walPath)
256				}
257				var rec walInstance
258				if err := json.Unmarshal(payload, &rec); err != nil || len(rec.InstanceID) == 0 || len(rec.InstanceID) > 64 {
259					return nil, fmt.Errorf("write-ahead log %s is corrupt: invalid instance marker: %w", walPath, err)
260				}
261				instanceID = rec.InstanceID
262				sawInstance = true
263			case recRegister, recTelemetry, recReplay:
264				if !sawInstance {
265					return nil, fmt.Errorf("write-ahead log %s is corrupt: data record precedes instance marker", walPath)
266				}
267				if err := applyRecord(store, recType, payload); err != nil {
268					return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: %w", walPath, pos, err)
269				}
270			default:
271				return nil, fmt.Errorf("write-ahead log %s uses unsupported record type %d at byte %d", walPath, recType, pos)
272			}
273			pos = end
274		}
275	
276		// Discard the unacknowledged tail so the file is exactly the committed
277		// prefix; these bytes belonged to a request that never returned success.
278		if int64(pos) < fi.Size() {
279			if err := f.Truncate(int64(pos)); err != nil {
280				return nil, fmt.Errorf("cannot discard unacknowledged tail of %s: %w", walPath, err)
281			}
282			if err := f.Sync(); err != nil {
283				return nil, fmt.Errorf("cannot flush truncated %s: %w", walPath, err)
284			}
285		}
286	
287		wal := &walFile{f: f, lock: lockFile, durable: int64(pos)}
288		if !sawInstance {
289			instanceID = newInstanceID()
290			if err := wal.appendRecord(recInstance, walInstance{InstanceID: instanceID}); err != nil {
291				return nil, fmt.Errorf("cannot write instance marker to %s: %w", walPath, err)
292			}
293		}
294		// Make freshly created directory entries durable as well.
295		if dirFile, err := os.Open(dir); err != nil {
296			return nil, fmt.Errorf("cannot open data directory %s for sync: %w", dir, err)
297		} else {
298			syncErr := syscall.Fsync(int(dirFile.Fd()))
299			_ = dirFile.Close()
300			if syncErr != nil {
301				return nil, fmt.Errorf("cannot flush data directory %s: %w", dir, syncErr)
302			}
303		}
304	
305		store.wal = wal
306		store.iid = instanceID
307		committed = true
308		return store, nil
309	}
310	
311	// Close releases the WAL and the directory lock.
312	func (s *Store) Close() error {
313		if closer, ok := s.wal.(interface{ Close() error }); ok {
314			return closer.Close()
315		}
316		return nil
317	}
318	
319	func storageUnavailable(err error) error {
320		return fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
321	}
322	
323	func walHeader() []byte {
324		header := make([]byte, headerLen)
325		copy(header[0:8], walMagic)
326		binary.LittleEndian.PutUint32(header[8:12], walVersion)
327		return header
328	}
329	
330	// marshalFrame frames one record as
331	// [length uint32 LE][type byte][payload][checksum8][commit marker 4].
332	// The checksum covers the whole phase-1 body (length, type and payload) and is
333	// the first 8 bytes of SHA-256. It returns the phase-1 body and the total
334	// committed frame length.
335	func marshalFrame(recType byte, value any) (body []byte, total int, err error) {
336		payload, err := json.Marshal(value)
337		if err != nil {
338			return nil, 0, err
339		}
340		if len(payload) > maxRecordPayload {
341			return nil, 0, fmt.Errorf("wal record too large: %d bytes", len(payload))
342		}
343		body = make([]byte, 5+len(payload)+8)
344		binary.LittleEndian.PutUint32(body[0:4], uint32(len(payload)))
345		body[4] = recType
346		copy(body[5:], payload)
347		sum := sha256.Sum256(body[:5+len(payload)])
348		copy(body[5+len(payload):], sum[:8])
349		return body, len(body) + len(commitMagic), nil
350	}
351	
352	const (
353		frameOK          = iota // checksum valid and commit marker present
354		frameUncommitted        // whole body present, marker missing (phase 1/2 not acknowledged)
355		frameTruncated          // declared frame runs past end of file (torn phase 1)
356		frameCorrupt            // commit marker present but the checksum fails
357	)
358	
359	// classifyFrame inspects the frame beginning at pos using the two-phase commit
360	// layout. The marker is written only after a complete, synced body, so:
361	//
362	//   - frameOK is a committed frame.
363	//   - frameCorrupt (marker present but the body fails its checksum) is bit-rot
364	//     of committed data and must fail startup.
365	//   - frameUncommitted / frameTruncated are residue from a write that never
366	//     reached its commit point (crash, or a request that returned 503). Recovery
367	//     treats them as an unacknowledged tail unless committed frames follow them
368	//     (hasCommittedChain), which would make them committed-history corruption.
369	func classifyFrame(data []byte, pos int) (status, end int, recType byte, payload []byte) {
370		if pos+5 > len(data) {
371			return frameTruncated, len(data), 0, nil
372		}
373		length := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
374		frameLen := 5 + length + 8 + len(commitMagic)
375		if length < 0 || length > maxRecordPayload || pos+frameLen > len(data) {
376			return frameTruncated, len(data), 0, nil
377		}
378		recType = data[pos+4]
379		payload = data[pos+5 : pos+5+length]
380		sum := sha256.Sum256(data[pos : pos+5+length])
381		checksumOK := bytes.Equal(sum[:8], data[pos+5+length:pos+5+length+8])
382		markerOK := string(data[pos+5+length+8:pos+frameLen]) == commitMagic
383		end = pos + frameLen
384		switch {
385		case checksumOK && markerOK:
386			return frameOK, end, recType, payload
387		case markerOK:
388			return frameCorrupt, end, 0, nil
389		default:
390			return frameUncommitted, end, 0, nil
391		}
392	}
393	
394	// hasCommittedChain reports whether valid committed frames chain contiguously
395	// from some offset after start to the exact end of data. Frames this server
396	// writes are contiguous, so finding one means the unusable bytes at start sit
397	// among committed records and must not be discarded.
398	func hasCommittedChain(data []byte, start int) bool {
399		for q := start + 1; q < len(data); q++ {
400			status, end, recType, _ := classifyFrame(data, q)
401			if status != frameOK || recType < recInstance || recType > recReplay {
402				continue
403			}
404			at := end
405			for at < len(data) {
406				next, nextEnd, nextType, _ := classifyFrame(data, at)
407				if next != frameOK || nextType < recInstance || nextType > recReplay {
408					break
409				}
410				at = nextEnd
411			}
412			if at == len(data) {
413				return true
414			}
415		}
416		return false
417	}
418	
419	// applyRecord rebuilds in-memory state from one committed record, rejecting
420	// any structural or relational inconsistency. It never calls the clock, so
421	// recovery cannot refresh device timestamps.
422	func applyRecord(s *Store, recType byte, payload []byte) error {
423		switch recType {
424		case recRegister:
425			var rec walRegister
426			if err := json.Unmarshal(payload, &rec); err != nil {
427				return fmt.Errorf("invalid register record: %w", err)
428			}
429			if rec.ID == "" || rec.RegisteredAt.IsZero() || rec.LastSeenAt.IsZero() {
430				return errors.New("register record missing fields")
431			}
432			if _, exists := s.devices[rec.ID]; exists {
433				return fmt.Errorf("duplicate registration for device %q", rec.ID)
434			}
435			s.devices[rec.ID] = &deviceState{
436				device: Device{
437					ID:           rec.ID,
438					Site:         rec.Site,
439					RegisteredAt: rec.RegisteredAt.UTC(),
440					LastSeenAt:   rec.LastSeenAt.UTC(),
441				},
442				byEvent: make(map[string]int64),
443				batches: make(map[string]storedBatch),
444			}
445			return nil
446	
447		case recTelemetry:
448			var rec walTelemetry
449			if err := json.Unmarshal(payload, &rec); err != nil {
450				return fmt.Errorf("invalid telemetry record: %w", err)
451			}
452			state, ok := s.devices[rec.DeviceID]
453			if !ok {
454				return fmt.Errorf("telemetry for unknown device %q", rec.DeviceID)
455			}
456			if rec.Sequence != int64(len(state.events))+1 {
457				return fmt.Errorf("device %q telemetry sequence gap: got %d, want %d", rec.DeviceID, rec.Sequence, len(state.events)+1)
458			}
459			if rec.ObservedAt.IsZero() || len(rec.Values) == 0 {
460				return fmt.Errorf("device %q telemetry record missing fields", rec.DeviceID)
461			}
462			state.events = append(state.events, Event{
463				Sequence:   rec.Sequence,
464				ObservedAt: rec.ObservedAt.UTC(),
465				Values:     cloneTelemetry(rec.Values),
466			})
467			state.device.LastSeenAt = rec.ObservedAt.UTC()
468			state.device.LastTelemetry = cloneTelemetry(rec.Values)
469			return nil
470	
471		case recReplay:
472			var rec walReplay
473			if err := json.Unmarshal(payload, &rec); err != nil {
474				return fmt.Errorf("invalid replay record: %w", err)
475			}
476			state, ok := s.devices[rec.DeviceID]
477			if !ok {
478				return fmt.Errorf("replay for unknown device %q", rec.DeviceID)
479			}
480			if rec.BatchID == "" || len(rec.Samples) == 0 || len(rec.Samples) != len(rec.Receipt.SampleStatus) {
481				return fmt.Errorf("device %q replay record is incomplete", rec.DeviceID)
482			}
483			if rec.Receipt.BatchID != rec.BatchID {
484				return fmt.Errorf("device %q receipt batchId %q does not match %q", rec.DeviceID, rec.Receipt.BatchID, rec.BatchID)
485			}
486			if _, exists := state.batches[rec.BatchID]; exists {
487				return fmt.Errorf("device %q duplicate stored receipt for batch %q", rec.DeviceID, rec.BatchID)
488			}
489	
490			samples := make([]Sample, len(rec.Samples))
491			newCount, dupCount := 0, 0
492			lastNew := -1
493			for i, entry := range rec.Samples {
494				status := rec.Receipt.SampleStatus[i]
495				if entry.EventID == "" || entry.ObservedAt.IsZero() || len(entry.Values) == 0 {
496					return fmt.Errorf("device %q batch %q sample %d is incomplete", rec.DeviceID, rec.BatchID, i)
497				}
498				if status.EventID != entry.EventID {
499					return fmt.Errorf("device %q batch %q receipt/sample eventId mismatch at %d", rec.DeviceID, rec.BatchID, i)
500				}
501				samples[i] = Sample{
502					EventID:    entry.EventID,
503					ObservedAt: entry.ObservedAt.UTC(),
504					Values:     cloneTelemetry(entry.Values),
505				}
506				if sequence, seen := state.byEvent[entry.EventID]; seen {
507					existing := state.events[sequence-1]
508					if !sameInstant(existing.ObservedAt, entry.ObservedAt) || !sameValues(existing.Values, entry.Values) {
509						return fmt.Errorf("device %q dedupe record for %q disagrees with history", rec.DeviceID, entry.EventID)
510					}
511					if !status.Duplicate || status.Sequence != sequence {
512						return fmt.Errorf("device %q receipt for %q should reuse sequence %d", rec.DeviceID, entry.EventID, sequence)
513					}
514					dupCount++
515					continue
516				}
517				if status.Duplicate {
518					return fmt.Errorf("device %q receipt marks unseen event %q as duplicate", rec.DeviceID, entry.EventID)
519				}
520				want := int64(len(state.events)) + 1
521				if status.Sequence != want {
522					return fmt.Errorf("device %q batch %q sequence mismatch for %q: got %d, want %d", rec.DeviceID, rec.BatchID, entry.EventID, status.Sequence, want)
523				}
524				state.events = append(state.events, Event{
525					Sequence:   status.Sequence,
526					ObservedAt: entry.ObservedAt.UTC(),
527					Values:     cloneTelemetry(entry.Values),
528				})
529				state.byEvent[entry.EventID] = status.Sequence
530				newCount++
531				lastNew = i
532			}
533			if rec.Receipt.NewCount != newCount || rec.Receipt.Duplicate != dupCount {
534				return fmt.Errorf("device %q batch %q receipt counts disagree with samples (%d/%d vs %d/%d)",
535					rec.DeviceID, rec.BatchID, rec.Receipt.NewCount, rec.Receipt.Duplicate, newCount, dupCount)
536			}
537	
538			if newCount > 0 {
539				if rec.LastSeenAt == nil || rec.LastSeenAt.IsZero() {
540					return fmt.Errorf("device %q batch %q missing recorded receive time", rec.DeviceID, rec.BatchID)
541				}
542				if !sameValues(rec.LastTelemetry, samples[lastNew].Values) {
543					return fmt.Errorf("device %q batch %q last telemetry disagrees with last new sample", rec.DeviceID, rec.BatchID)
544				}
545				state.device.LastSeenAt = rec.LastSeenAt.UTC()
546				state.device.LastTelemetry = cloneTelemetry(rec.LastTelemetry)
547			} else if rec.LastSeenAt != nil || len(rec.LastTelemetry) != 0 {
548				return fmt.Errorf("device %q all-duplicate batch %q unexpectedly refreshed device state", rec.DeviceID, rec.BatchID)
549			}
550	
551			state.batches[rec.BatchID] = storedBatch{samples: samples, receipt: cloneReceipt(rec.Receipt)}
552			return nil
553	
554		default:
555			return fmt.Errorf("unknown record type %d", recType)
556		}
557	}
558	
559	func newInstanceID() []byte {
560		id := make([]byte, 16)
561		if _, err := rand.Read(id); err != nil {
562			panic(fmt.Sprintf("cannot generate instance id: %v", err))
563		}
564		return id
565	}
566

