241		// Data files must be untouched: first process can still write.
242		h := NewHandler(first)
243		mustRegister(t, h, "gw")
244	
245		if err := first.Close(); err != nil {
246			t.Fatal(err)
247		}
248		// After exit (including a killed process releasing the kernel lock) the
249		// directory reopens without manual cleanup.
250		again := reopenPersistent(t, dir)
251		if !again.Exists("gw") {
252			t.Fatalf("device missing after lock release and reopen")
253		}
254	}
