256	// --- damaged committed data fails startup and is left untouched ------------
257	
258	func TestPersistentCorruptCommittedRecordFailsStartup(t *testing.T) {
259		dir := t.TempDir()
260		store := openPersistent(t, dir)
261		h := NewHandler(store)
262		mustRegister(t, h, "a")
263		mustRegister(t, h, "b")
264		mustRegister(t, h, "c")
265		if err := store.Close(); err != nil {
266			t.Fatal(err)
267		}
268	
269		raw := walRaw(t, dir)
270		// Locate the second committed frame (a register record) and flip a payload
271		// byte; its checksum then fails (commit marker still present) while later
272		// committed frames remain intact.
273		pos := headerLen
274		status, end, _, _ := classifyFrame(raw, pos)
275		if status != frameOK {
276			t.Fatalf("first frame invalid: %d", status)
277		}
278		secondPos := end
279		status, end2, _, _ := classifyFrame(raw, secondPos)
280		if status != frameOK {
281			t.Fatalf("second frame invalid: %d", status)
282		}
283		target := secondPos + 5 + 2 // inside payload
284		original := raw[target]
285		raw[target] = original ^ 0xFF
286		if err := os.WriteFile(filepath.Join(dir, walName), raw, 0o600); err != nil {
287			t.Fatal(err)
288		}
289		_ = end2
290	
291		if _, err := NewPersistentStore(dir); err == nil {
292			t.Fatalf("startup succeeded with corrupt committed record")
293		} else if !strings.Contains(err.Error(), "corrupt") {
294			t.Fatalf("error = %v, want corruption message", err)
295		}
296	
297		// The damaged file is left exactly as found.
298		after := walRaw(t, dir)
299		if string(after) != string(raw) {
300			t.Fatalf("corrupt wal was modified by failed startup")
301		}
302	}
