365	// --- runtime write failure returns 503 and changes nothing ------------------
366	
367	type failingWAL struct {
368		inner    *walFile
369		failOnce bool
370		mu       sync.Mutex
371		didFail  bool
372	}
373	
374	func (w *failingWAL) appendRecord(recType byte, value any) error {
375		w.mu.Lock()
376		defer w.mu.Unlock()
377		if !w.didFail {
378			w.didFail = true
379			// Leave residue from an interrupted write at the commit boundary,
380			// without the commit marker and without advancing durable.
381			if err := pwriteAll(w.inner.f, []byte{0xff, 0xff, 0xff, 0xff, 0x12}, w.inner.durable); err != nil {
382				return err
383			}
384			return fmt.Errorf("simulated disk failure")
385		}
386		return w.inner.appendRecord(recType, value)
387	}
