389	func TestPersistentWriteFailureReturns503AndRetries(t *testing.T) {
390		dir := t.TempDir()
391		store := openPersistent(t, dir)
392		h := NewHandler(store)
393		mustRegister(t, h, "gw")
394	
395		// Fail the first telemetry write at the storage layer.
396		real := store.wal.(*walFile)
397		failing := &failingWAL{inner: real}
398		store.wal = failing
399	
400		r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":1}`)
401		if r.Code != http.StatusServiceUnavailable {
402			t.Fatalf("failing write status = %d, want 503: %s", r.Code, r.Body.String())
403		}
404	
405		// Queryable state is unchanged and no sequence was consumed.
406		events := allEvents(t, h, "gw")
407		if len(events) != 0 {
408			t.Fatalf("failed write left events: %+v", events)
409		}
410	
411		// Once writes succeed again, the same request commits at sequence 1 and
412		// overwrites the residue the failed attempt left behind.
413		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/telemetry", `{"temperature":1}`)
414		if r.Code != http.StatusAccepted {
415			t.Fatalf("retried write = %d: %s", r.Code, r.Body.String())
416		}
417		events = allEvents(t, h, "gw")
418		if len(events) != 1 || events[0].Sequence != 1 {
419			t.Fatalf("retry did not commit at sequence 1: %+v", events)
420		}
421	
422		// A failing replay must not reserve sequences or leave a receipt.
423		failing.didFail = false
424		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
425			replayBody("batch-x", sample("x1", "2024-01-03T10:00:00Z", `{"v":9}`)))
426		if r.Code != http.StatusServiceUnavailable {
427			t.Fatalf("failing replay = %d, want 503", r.Code)
428		}
429		events = allEvents(t, h, "gw")
430		if len(events) != 1 {
431			t.Fatalf("failed replay consumed a sequence: %+v", events)
432		}
433		r = doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
434			replayBody("batch-x", sample("x1", "2024-01-03T10:00:00Z", `{"v":9}`)))
435		if r.Code != http.StatusAccepted {
436			t.Fatalf("retry of failed replay = %d, want 202 (no prior receipt): %s", r.Code, r.Body.String())
437		}
438		events = allEvents(t, h, "gw")
439		if len(events) != 2 || events[1].Sequence != 2 {
440			t.Fatalf("replay retry sequence = %+v", events)
441		}
442	
443		// Reopening the real log proves the residue never became visible.
444		store.wal = real
445		if err := store.Close(); err != nil {
446			t.Fatal(err)
447		}
448		store2 := reopenPersistent(t, dir)
449		h2 := NewHandler(store2)
450		events = allEvents(t, h2, "gw")
451		if len(events) != 2 {
452			t.Fatalf("recovered history = %+v", events)
453		}
454	}
