456	// --- replay batch atomicity across a crash ----------------------------------
457	func TestPersistentReplayIsOneCommitUnit(t *testing.T) {
458		dir := t.TempDir()
459		store := openPersistent(t, dir)
460		h := NewHandler(store)
461		mustRegister(t, h, "gw")
462	
463		// Commit a three-sample batch, then append a *complete but unmarked* frame
464		// (phase 1 survived, phase 2 did not): recovery must expose none of it.
465		good := replayBody("good",
466			sample("g1", "2024-01-02T10:00:00Z", `{"v":1}`),
467			sample("g2", "2024-01-02T11:00:00Z", `{"v":2}`),
468			sample("g3", "2024-01-02T12:00:00Z", `{"v":3}`),
469		)
470		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", good); r.Code != http.StatusAccepted {
471			t.Fatalf("good batch = %d", r.Code)
472		}
473		if err := store.Close(); err != nil {
474			t.Fatal(err)
475		}
476	
477		// Hand-craft an unmarked body for another batch and append it.
478		body, _, err := marshalFrame(recReplay, walReplay{
479			DeviceID: "gw",
480			BatchID:  "lost",
481			Samples: []walSample{
482				{EventID: "l1", ObservedAt: time.Date(2024, 1, 4, 0, 0, 0, 0, time.UTC), Values: map[string]float64{"v": 4}},
483			},
484			Receipt: ReplayReceipt{
485				BatchID:      "lost",
486				NewCount:     1,
487				SampleStatus: []SampleStatus{{EventID: "l1", Sequence: 4, Duplicate: false}},
488			},
489		})
490		if err != nil {
491			t.Fatal(err)
492		}
493		raw := walRaw(t, dir)
494		raw = append(raw, body...) // body excludes the commit marker
495		if err := os.WriteFile(filepath.Join(dir, walName), raw, 0o600); err != nil {
496			t.Fatal(err)
497		}
498	
499		store2 := reopenPersistent(t, dir)
500		h2 := NewHandler(store2)
501		events := allEvents(t, h2, "gw")
502		if len(events) != 3 {
503			t.Fatalf("uncommitted batch partially visible: %+v", events)
504		}
505		// The batch never committed, so resubmitting it is a fresh 202 at seq 4.
506		r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
507			replayBody("lost", sample("l1", "2024-01-04T00:00:00Z", `{"v":4}`)))
508		if r.Code != http.StatusAccepted {
509			t.Fatalf("uncommitted batch retry = %d, want 202", r.Code)
510		}
511		receipt := decodeBody[receiptResponse](t, r)
512		if receipt.Samples[0].Sequence != 4 {
513			t.Fatalf("sequence = %d, want 4", receipt.Samples[0].Sequence)
514		}
515	}
