517	// --- durable mode keeps atomicity under concurrency -------------------------
518	
519	func TestPersistentConcurrentWrites(t *testing.T) {
520		dir := t.TempDir()
521		store := openPersistent(t, dir)
522		h := NewHandler(store)
523		mustRegister(t, h, "gw")
524	
525		var start, wg sync.WaitGroup
526		start.Add(1)
527		for g := 0; g < 16; g++ {
528			wg.Add(1)
529			go func(g int) {
530				defer wg.Done()
531				start.Wait()
532				samples := make([]string, 4)
533				for i := range samples {
534					samples[i] = sample(fmt.Sprintf("g%d-e%d", g, i), "2024-01-02T10:00:00Z", fmt.Sprintf(`{"g":%d}`, g))
535				}
536				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay", replayBody(fmt.Sprintf("batch-g%d", g), samples...))
537				if r.Code != http.StatusAccepted {
538					t.Errorf("group %d = %d: %s", g, r.Code, r.Body.String())
539				}
540			}(g)
541		}
542		codes := map[int]int{}
543		var codesMu sync.Mutex
544		for c := 0; c < 10; c++ {
545			wg.Add(1)
546			go func() {
547				defer wg.Done()
548				start.Wait()
549				r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/replay",
550					replayBody("dup", sample("dup-event", "2024-01-02T10:00:00Z", `{"v":1}`)))
551				codesMu.Lock()
552				codes[r.Code]++
553				codesMu.Unlock()
554			}()
555		}
556		start.Done()
557		wg.Wait()
558		if codes[http.StatusAccepted] != 1 || codes[http.StatusOK] != 9 {
559			t.Fatalf("dup codes = %v", codes)
560		}
561		events := allEvents(t, h, "gw")
562		if len(events) != 16*4+1 {
563			t.Fatalf("events = %d, want %d", len(events), 16*4+1)
564		}
565		for i, event := range events {
566			if event.Sequence != int64(i+1) {
567				t.Fatalf("non-contiguous sequence at %d: %d", i, event.Sequence)
568			}
569		}
570	
571		// Restart: the same concurrent result must recover exactly.
572		if err := store.Close(); err != nil {
573			t.Fatal(err)
574		}
575		store2 := reopenPersistent(t, dir)
576		h2 := NewHandler(store2)
577		recovered := allEvents(t, h2, "gw")
578		if len(recovered) != len(events) {
579			t.Fatalf("recovered events = %d, want %d", len(recovered), len(events))
580		}
581		// Re-hammering the dup batch after restart is still a single first receipt.
582		r := doRequest(t, h2, http.MethodPost, "/v1/devices/gw/replay",
583			replayBody("dup", sample("dup-event", "2024-01-02T10:00:00Z", `{"v":1}`)))
584		if r.Code != http.StatusOK {
585			t.Fatalf("post-restart dup = %d, want 200", r.Code)
586		}
587	}
