func (w *failingWAL) appendRecord(recType byte, value any) error {
	w.mu.Lock()
	defer w.mu.Unlock()
	if !w.didFail {
		w.didFail = true
		// Leave residue from an interrupted write at the commit boundary,
		// without the commit marker and without advancing durable.
		if err := pwriteAll(w.inner.f, []byte{0xff, 0xff, 0xff, 0xff, 0x12}, w.inner.durable); err != nil {
			return err
		}
		return fmt.Errorf("simulated disk failure")
	}
	return w.inner.appendRecord(recType, value)
}

